import{_ as i,l as n,o as e,c as l,v as t,p as d,x as o,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"暗池、ATS 与中点单","description":"","frontmatter":{"title":"暗池、ATS 与中点单","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dark-pool-midpoint.md","filePath":"quant/dark-pool-midpoint.md","lastUpdated":1789023840000}'),B={name:"quant/dark-pool-midpoint.md"};function E(m,a,u,A,c,T){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="暗池、ats-与中点单" tabindex="-1">暗池、ATS 与中点单 <a class="header-anchor" href="#暗池、ats-与中点单" aria-label="Permalink to &quot;暗池、ATS 与中点单&quot;">​</a></h1><div class="epigraph"><p>不展示买卖报价的场所把匹配移到公开栅格内部，最常见的锚是公开中点。事前透明被牺牲，换的是更少的展示冲击，以及更难检验的对手方。</p><footer>—— 据 Ready, The Tale of Two Exchanges, 以及 Zhu 对暗池与知情交易选择的理论；对照 SEC 对 ATS 的公开披露框架</footer></div><p><a href="/quant/price-grid-tick">价格栅格</a>说明公开限价不能挂在半 tick 中点上。<a href="/quant/order-types">订单类型</a>已经把暗池当成一种场所，没有写匹配锚与分段后的会计。本课的缺口是市场设计：ATS / 暗池用什么价格成交（中点、参考价改善、定期交叉）、谁被允许进来、成交如何打印回公开磁带。Ready 比较不同结构的执行成本；Zhu 问知情者会不会更爱暗处。后课的市场分割把暗池放进多场所系统；本课只把中点协议写清楚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开连续簿的状态是 BBO 与深度。暗池的状态常常只有：你的单是否还在、有时有指示性量，没有公开的对方报价。中点单（midpoint peg / midpoint cross）把成交价钉在当时公开中点 \\(m\\)，买卖双方各让一半展示价差。对 taker 这是价格改善；对 maker 这是放弃报价价差、只赚（可能的）回扣或减少信息泄露。问题是 \\(m\\) 来自哪一张公开簿、延迟多少、以及暗池里的对手是不是知情者。</p><p>若中点来自已经过时的 SIP，\\(m\\) 可能已经被直连报价越过，中点成交其实是在过时的「中间」成交，经济上偏向一方。这与后课 SIP 对照衔接，本课先记下：中点协议寄生在公开报价上，公开报价的时钟质量就是暗池的定价质量。Zhu 的机制是：知情者在暗处隐藏规模，非知情者提供中点流动性时承担逆向选择。暗池不是免费的中点。</p><h3 id="中点、参考价改善与定期交叉不是同一种-ats" tabindex="-1">中点、参考价改善与定期交叉不是同一种 ATS <a class="header-anchor" href="#中点、参考价改善与定期交叉不是同一种-ats" aria-label="Permalink to &quot;中点、参考价改善与定期交叉不是同一种 ATS&quot;">​</a></h3><p>中点撮合：买卖单在 \\(m\\) 上配对，常要求最小数量、或禁止会锁定公开市场的价格。参考价改善：允许在 \\(m\\) 与 BBO 之间的价格成交。定期交叉：像迷你集合竞价，每隔一段时间用中点或出清价批量配对。三者的价差会计不同。中点成交的有效价差相对当时 \\(m\\) 接近零，但不能说成本为零——你承担了等待、不成交、以及对手知情时的事后冲击。定期交叉更接近<a href="/quant/continuous-vs-auction">集合竞价</a>，只是锚通常仍是公开中点。</p><p><span class="marginnote">「暗」指事前不展示报价，不是事后永不打印。美股成交仍须向磁带报告；延迟与场所代码决定研究能否把它从公开成交里认出来。A 股没有对等的股票暗池生态，本课的制度对象以 ATS 文献为主，对照写在边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行会计把暗池成交单独成列：到达中点、等待时长、成交价相对到达时公开中点、成交价相对成交时公开中点（两者因延迟可能不同）、以及随后 \\(\\tau\\) 的实现价差。相对到达中点的偏差度量时钟；随后中点移动度量逆向选择。Comerton-Forde 与 Putniņš 等对暗池份额与价格发现的经验工作，问的是暗成交增加时公开市场质量变好还是变差，而不是「暗池里省了半个价差」。</p><p>样本要按场所类型分：竞价交易所、做市商内化、中点 ATS、零售批发。全部混成「场外」会把零售改善与机构暗池挤在一个均值里。没有场所代码时，只能用「成交在公开 BBO 内部」当粗糙代理，该代理也包含零股与本所隐藏单，见<a href="/quant/lot-size-odd-lot">手数</a>。</p><h3 id="准入、分段与规模筛选" tabindex="-1">准入、分段与规模筛选 <a class="header-anchor" href="#准入、分段与规模筛选" aria-label="Permalink to &quot;准入、分段与规模筛选&quot;">​</a></h3><p>许多 ATS 对参与者做分段：零售、机构、高频。分段是为了降低毒性，等于在暗处做对手方选择。研究若把所有中点成交当同质，会低估分段场所的实现价差、高估开放场所的。规模筛选（minimum quantity）把小的探测单挡在外面，大单才匹配，这改变了冰山式的信息泄露，也改变了填成率。方法是把场所规则当成执行算法的状态，而不是当成一个滑点常数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中点协议把公开价差的一半做成匹配锚。公开做市商仍在格子上报价，为全市场生产 \\(m\\)；暗池免费（或几乎免费）使用这个锚。于是出现搭便车：展示流动性的激励下降，中点成交的份额上升，公开深度可能变薄。这是市场设计的反馈，不是道德批评。若公开 BBO 变宽，\\(m\\) 的质量下降，中点成交的「改善」以更差的锚为参照，改善是幻觉。</p><p>信息写入：暗成交若延迟打印，公开簿短时间内不知道发生过交易。知情买入可以先在暗处吸量，再出现在公开跳价里。价格发现的领先滞后会偏向公开报价场所，即使成交量已经大量离开。Hasbrouck 式份额用报价新息，暗池没有报价，份额自然不算它——这是度量的盲区，不是暗池没有信息。</p><p><span class="marginnote">不要用 <a href="/quant/roll-model">Roll</a> 去估暗池价差：暗池经常没有买卖回跳，成交钉在中点，协方差结构被设计成接近零。有效价差相对 \\(m\\) 也接近零。有信息的是实现价差和填成率。</span></p>',18)),(e(),d(h,null,{default:o(()=>[p(r,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TB%0A%20%20P%5B%22%E5%85%AC%E5%BC%80%20BBO%22%5D%20--%3E%20M%5B%22%E4%B8%AD%E7%82%B9%20m%22%5D%0A%20%20M%20--%3E%20D%5B%22%E6%9A%97%E6%B1%A0%E4%B8%AD%E7%82%B9%E6%92%AE%E5%90%88%22%5D%0A%20%20D%20--%3E%20F%5B%22%E6%88%90%E4%BA%A4%EF%BC%9A%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E2%89%880%22%5D%0A%20%20D%20--%3E%20I%5B%22%E4%BA%8B%E5%90%8E%EF%BC%9A%E5%AE%9E%E7%8E%B0%E4%BB%B7%E5%B7%AE%E4%B8%8E%E4%B8%AD%E7%82%B9%E6%BC%82%E7%A7%BB%22%5D%0A%20%20F%20--%3E%20T%5B%22%E7%A3%81%E5%B8%A6%E5%BB%B6%E8%BF%9F%E6%89%93%E5%8D%B0%22%5D%0A%20%20T%20--%3E%20P%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="中点锚的延迟就是暗池的定价误差" tabindex="-1">中点锚的延迟就是暗池的定价误差 <a class="header-anchor" href="#中点锚的延迟就是暗池的定价误差" aria-label="Permalink to &quot;中点锚的延迟就是暗池的定价误差&quot;">​</a></h3><p>锚若来自过时 SIP，\\(m\\) 已不是可成交中间。实现价差会把管道延迟写成逆向选择。对照应同时报到达中点与成交中点，分叉归时钟，漂移归信息。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>欧洲的暗交易限制、美股对 ATS 的透明度规则、中国股票市场几乎不存在对等暗池，不能互相外推结论。债券、CDS 的「暗」是 OTC 询价，见<a href="/quant/corporate-bond-otc">公司债 OTC</a>，匹配锚不是股票 SIP 中点。加密的非展示订单在中心化交易所内部，法律地位与 ATS 不同。</p><p><span class="marginnote">A 股没有对等 ATS 中点生态。把美股暗池改善率搬到沪深连续竞价，制度对象不存在。</span></p><p>本课不讨论如何识别或规避暗池里的有毒对手，只要求：中点不是免费午餐，锚的时钟和对手方分段决定实现成本。下一课把暗池放进多场所与 NBBO 的系统里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中点单寄生在公开 BBO 上；公开报价的时钟就是暗池的定价质量。</li><li>有效价差接近零不表示成本为零，要实现价差、等待与不成交。</li><li>中点撮合、改善撮合、定期交叉是三种 ATS，会计不同。</li><li>分段与最小数量改变毒性，不能把所有暗成交当同质。</li><li>暗成交挤出展示深度时，中点锚本身会变差。</li><li>出处：Zhu, <em>RFS</em>, 2014；Ready 对执行场所的比较；Comerton-Forde and Putniņš 等对暗池与价格发现的经验工作；SEC ATS 披露文件。</li></ul>',8))])}const f=i(B,[["render",E]]);export{_ as __pageData,f as default};
